{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 유기동물로 구조된 길고양이의 공고기간 후 중성화 방사 가능 여부 및 구조 장소가 위험한 경우 안전한 다른 장소 지정 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제22조제3항에 따르면, 시장 또는 구청장은 유기동물로 구조되어 제11조에 따른 공고기간이 지난 길고양이의 경우 중성화하여 구조 장소에 방사할 수 있습니다. 같은 조례 제22조제2항 단서는 길고양이의 안전과 보호를 위해 필요한 경우 다른 장소를 정하여 방사할 수 있도록 정하고 있으며, 제22조제3항은 이 단서 규정을 준용합니다. 따라서 공고기간이 지난 구조 길고양이를 중성화한 뒤 방사하는 것은 가능하고, 구조 장소가 위험한 등 길고양이의 안전과 보호를 위해 필요한 경우에는 안전한 다른 장소를 정하여 방사할 수 있습니다.",
          "b_ids": "동물보호:제22조제3항, 동물보호:제22조제2항단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
